(function(){var host=document.querySelector('.hero-bg');if(!host)return;var c=navigator.connection;if(matchMedia('(prefers-reduced-motion: reduce)').matches||(c&&c.saveData))return;var cv=document.createElement('canvas');cv.setAttribute('aria-hidden','true');cv.style.cssText='position:absolute;inset:0;width:100%;height:100%;display:block;pointer-events:none;opacity:0;transition:opacity 1.4s';var gl=cv.getContext('webgl',{alpha:true,antialias:false,powerPreference:'low-power'});if(!gl)return;var VS='attribute vec2 position;void main(){gl_Position=vec4(position,0.0,1.0);}';var FS=['#ifdef GL_FRAGMENT_PRECISION_HIGH','precision highp float;','#else','precision mediump float;','#endif','uniform float iTime;uniform vec2 iResolution;uniform vec2 rayPos;uniform vec2 rayDir;uniform vec2 mousePos;','const vec3 RAYS=vec3(0.933,0.314,0.004);const float SPEED=1.2,SPREAD=1.1,LEN=1.6,FADE=1.0,DIST=0.06,MOUSE=0.12,NOISE=0.03;','float noise(vec2 s){return fract(sin(dot(s,vec2(12.9898,78.233)))*43758.5453123);}','float ray(vec2 src,vec2 ref,vec2 p,float sa,float sb,float sp){',' vec2 d=p-src;vec2 n=normalize(d);float ca=dot(n,ref);',' float da=ca+DIST*sin(iTime*1.5+length(d)*0.005);',' float spread=pow(max(da,0.0),1.0/max(SPREAD,0.001));',' float dist=length(d);float mx=max(iResolution.x,iResolution.y);',' float lf=clamp((mx*LEN-dist)/(mx*LEN),0.0,1.0);float ff=clamp((FADE*mx-dist)/(FADE*mx),0.0,1.0);',' float b=clamp((0.5+0.2*sin(da*sa+iTime*sp))+(0.3+0.2*cos(-da*sb+iTime*sp*0.8)),0.0,1.0);',' return b*lf*ff*spread;}','void main(){vec2 p=gl_FragCoord.xy;vec2 dir=normalize(rayDir);',' vec2 md=normalize(mousePos*iResolution-rayPos);dir=normalize(mix(dir,md,MOUSE));',' float r=ray(rayPos,dir,p,45.2,31.4,0.8*SPEED)*0.4+ray(rayPos,dir,p,28.5,19.8,1.2*SPEED)*0.4+ray(rayPos,dir,p,12.1,56.2,0.5*SPEED)*0.2;',' r=pow(r,0.7)*1.5;float a=clamp(r*0.42,0.0,1.0);vec3 col=RAYS*a;',' col*=1.0-NOISE+NOISE*noise(p*0.01+iTime*0.05);gl_FragColor=vec4(col,a);}'].join('\n');function sh(t,s){var o=gl.createShader(t);gl.shaderSource(o,s);gl.compileShader(o);return gl.getShaderParameter(o,gl.COMPILE_STATUS)?o:null}
var v=sh(gl.VERTEX_SHADER,VS),f=sh(gl.FRAGMENT_SHADER,FS);if(!v||!f)return;var pr=gl.createProgram();gl.attachShader(pr,v);gl.attachShader(pr,f);gl.linkProgram(pr);if(!gl.getProgramParameter(pr,gl.LINK_STATUS))return;gl.useProgram(pr);var b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);var loc=gl.getAttribLocation(pr,'position');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);var U=function(n){return gl.getUniformLocation(pr,n)},uT=U('iTime'),uR=U('iResolution'),uP=U('rayPos'),uD=U('rayDir'),uM=U('mousePos');host.appendChild(cv);var W=1,H=1;function size(){var s=Math.min(devicePixelRatio||1,1.5)*0.7;W=Math.max(2,Math.round(host.clientWidth*s));H=Math.max(2,Math.round(host.clientHeight*s));cv.width=W;cv.height=H;gl.viewport(0,0,W,H)}
size();if('ResizeObserver'in window)new ResizeObserver(size).observe(host);else addEventListener('resize',size);var tx=.5,ty=.5,sx=.5,sy=.5;addEventListener('pointermove',function(e){tx=e.clientX/innerWidth;ty=1-e.clientY/innerHeight},{passive:true});var on=true,raf=0,t0=performance.now();function frame(now){raf=0;if(!on||document.hidden)return;sx+=(tx-sx)*.05;sy+=(ty-sy)*.05;gl.uniform1f(uT,(now-t0)/1000);gl.uniform2f(uR,W,H);gl.uniform2f(uP,W*.5,H*1.2);gl.uniform2f(uD,0,-1);gl.uniform2f(uM,sx,sy);gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);gl.drawArrays(gl.TRIANGLES,0,3);cv.style.opacity=1;raf=requestAnimationFrame(frame)}
function go(){if(!raf)raf=requestAnimationFrame(frame)}
if('IntersectionObserver'in window)new IntersectionObserver(function(e){on=e[0].isIntersecting;if(on)go()}).observe(host);document.addEventListener('visibilitychange',go);go();})();